var REGOP_CONTEUDO_MODULO = "<style>\n/* Variáveis de cor do módulo — faltavam (--accent, --accent-2, --input,\n   --panel, --shadow-soft, --text-strong, --muted-2, --surface-2), causando\n   texto sem contraste e cartões sem fundo em toda a tela (bug real\n   encontrado em 2026-08-21, mesmo problema do PGT e POP/CronExec/Inventário).\n   As demais (--bg, --text, --border etc.) já vêm do tema global do Portal. */\n#tplRegOpContainer {\n  --accent: var(--bc-action);\n  --accent-2: var(--bc-action);\n  --input: #FFFFFF;\n  --panel: var(--bc-surface);\n  --shadow-soft: none;\n  --text-strong: var(--bc-text);\n  --muted-2: var(--bc-text-3);\n  --surface-2: var(--bc-surface-2);\n}\n#tplRegOpContainer, #tplRegOpContainer body {\n  font-family: var(--bc-sans);\n}\n\n/* Manual do Operador — mesmo padrão visual dos outros módulos do Portal */\n#tplRegOpContainer .manual-wrap { max-width: 900px; margin: 0 auto; padding: 18px 18px 60px; line-height: 1.6; }\n#tplRegOpContainer .manual-wrap h1 { font-size: 26px; margin-bottom: 4px; }\n#tplRegOpContainer .manual-wrap .subtitulo { color: var(--muted); margin-top: 0; margin-bottom: 22px; }\n#tplRegOpContainer .manual-wrap h2 { font-size: 19px; margin-top: 40px; padding-bottom: 8px; border-bottom: 1px solid var(--border); color: var(--text-strong); }\n#tplRegOpContainer .manual-wrap h3 { font-size: 15px; margin-top: 26px; color: var(--accent-2); }\n#tplRegOpContainer .manual-wrap p { color: var(--text); }\n#tplRegOpContainer .manual-wrap table { width: 100%; border-collapse: collapse; margin: 14px 0 22px; font-size: 13.5px; }\n#tplRegOpContainer .manual-wrap th, #tplRegOpContainer .manual-wrap td { border: 1px solid var(--border); padding: 8px 10px; text-align: left; vertical-align: top; }\n#tplRegOpContainer .manual-wrap th { background: #FFFFFF; color: var(--text-strong); }\n#tplRegOpContainer .manual-wrap tr:nth-child(even) td { background: var(--bc-surface-2); }\n#tplRegOpContainer .callout { background: var(--bc-action-bg); border: 1px solid var(--bc-action-line); border-left: 4px solid var(--accent); border-radius: var(--radius-sm); padding: 12px 14px; margin: 14px 0; font-size: 13.5px; }\n#tplRegOpContainer .callout strong { color: var(--text-strong); }\n#tplRegOpContainer .manual-wrap ol, #tplRegOpContainer .manual-wrap ul { padding-left: 22px; }\n#tplRegOpContainer .manual-wrap ol li, #tplRegOpContainer .manual-wrap ul li { margin-bottom: 6px; }\n#tplRegOpContainer .toc { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px 20px; margin-bottom: 30px; }\n#tplRegOpContainer .toc h2 { margin-top: 0; border-bottom: none; font-size: 15px; }\n#tplRegOpContainer .toc ol { columns: 2; column-gap: 30px; }\n#tplRegOpContainer .toc a { text-decoration: none; color: var(--accent-2); cursor: pointer; }\n#tplRegOpContainer .toc a:hover { text-decoration: underline; }\n#tplRegOpContainer .topo-link { display: inline-block; margin-top: 30px; }\n\n#tplRegOpContainer * { box-sizing: border-box; }\n#tplRegOpContainer img { max-width: 100%; }\n#tplRegOpContainer a { color: var(--accent-2); }\n#tplRegOpContainer .hidden { display: none !important; }\n#tplRegOpContainer .wrap { max-width: 100%; margin: 0; padding: 18px; }\n#tplRegOpContainer .header-card {\n  background: #FFFFFF;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 14px 18px;\n  box-shadow: var(--shadow-soft);\n  margin-bottom: 14px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 14px;\n}\n#tplRegOpContainer .title-area h1 { margin: 0; font-size: 19px; color: var(--text-strong); font-weight: 800; }\n#tplRegOpContainer .title-area p { margin: 5px 0 0; color: var(--muted); font-size: 13px; }\n#tplRegOpContainer .step-nav { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }\n#tplRegOpContainer .step-nav-item {\n  flex: 1; min-width: 110px; text-align: center; padding: 8px 6px; border-radius: var(--radius-sm);\n  background: var(--surface-2); border: 1px solid var(--border); color: var(--muted); font-size: 11.5px; font-weight: 700;\n}\n#tplRegOpContainer .step-nav-item.active { background: var(--accent); color: var(--text-strong); border-color: var(--accent); }\n#tplRegOpContainer .step-nav-item.done { color: var(--success); border-color: var(--success); }\n#tplRegOpContainer .step { display: none; }\n#tplRegOpContainer .step.active { display: block; }\n#tplRegOpContainer .panel {\n  background: #FFFFFF;\n  border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow-soft); border: 1px solid var(--border);\n}\n#tplRegOpContainer .panel h2 {\n  margin: 0 0 16px; font-size: 14px; color: var(--text-strong); border-bottom: 1px solid var(--border);\n  padding-bottom: 11px; text-transform: uppercase;\n}\n#tplRegOpContainer .section-divider {\n  margin: 22px 0 14px; padding: 8px 10px; border: 1px solid var(--border); border-left: 3px solid var(--accent-2);\n  background: #FFFFFF; border-radius: 6px; font-size: 12px; font-weight: 800; color: var(--info);\n  text-transform: uppercase;\n}\n#tplRegOpContainer .form-row { display: flex; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }\n#tplRegOpContainer .form-group { flex: 1; min-width: 160px; }\n#tplRegOpContainer .form-group.w-100 { flex: 1 1 100%; }\n#tplRegOpContainer .form-group label { display: block; margin-bottom: 6px; font-size: 12px; font-weight: 700; color: var(--text); }\n#tplRegOpContainer .form-control {\n  width: 100%; min-height: 30px; padding: 5px 9px; border: 1px solid var(--border); border-radius: var(--radius-sm);\n  font-size: 12.5px; color: var(--text); background: var(--input);\n}\n#tplRegOpContainer textarea.form-control { min-height: 70px; resize: vertical; font-family: inherit; }\n#tplRegOpContainer select.form-control { cursor: pointer; }\n#tplRegOpContainer .form-control:focus { outline: none; border-color: var(--accent-2); }\n#tplRegOpContainer .field-help { display: block; margin-top: 6px; font-size: 11px; color: var(--muted-2); line-height: 1.45; }\n#tplRegOpContainer .btn {\n  padding: 7px 14px; border: 1px solid transparent; border-radius: var(--radius-sm); font-weight: 800;\n  font-size: 12.5px; cursor: pointer; min-height: 30px;\n}\n#tplRegOpContainer .btn:disabled { opacity: 0.55; cursor: not-allowed; }\n#tplRegOpContainer .btn-primary { background: var(--accent); color: var(--text-strong); }\n#tplRegOpContainer .btn-secondary { background: var(--card-soft); color: var(--text-strong); border: 1px solid var(--border); }\n#tplRegOpContainer .btn-danger { background: var(--danger); color: #fff; }\n#tplRegOpContainer .btn-xs { padding: 4px 10px; min-height: 24px; font-size: 11px; }\n#tplRegOpContainer .btn-container { display: flex; gap: 10px; margin-top: 18px; flex-wrap: wrap; }\n#tplRegOpContainer .alert-box { margin-top: 14px; border-radius: var(--radius-sm); padding: 9px 11px; font-size: 12px; border: 1px solid transparent; }\n#tplRegOpContainer .alert-box.info { background: var(--bc-info-bg); color: var(--info); border-color: var(--bc-info-line); }\n#tplRegOpContainer .alert-box.warning { background: var(--bc-warn-bg); color: var(--warning); border-color: var(--bc-warn-line); }\n#tplRegOpContainer .alert-box.error { background: var(--bc-danger-bg); color: var(--danger); border-color: var(--bc-danger-line); }\n#tplRegOpContainer .alert-box.success { background: var(--bc-action-bg); color: var(--success); border-color: var(--bc-action-line); }\n#tplRegOpContainer .item-checklist {\n  background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius-sm);\n  padding: 10px 12px; margin-bottom: 8px;\n}\n#tplRegOpContainer .item-checklist-edit { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }\n#tplRegOpContainer .item-checklist-edit input[type=\"text\"] { flex: 1; min-width: 180px; }\n#tplRegOpContainer .item-checklist-edit select { width: 140px; }\n#tplRegOpContainer .item-checklist-preenchimento .item-texto { font-size: 12.5px; color: var(--text-strong); font-weight: 700; margin-bottom: 8px; }\n#tplRegOpContainer .resposta-opcoes { display: flex; gap: 14px; margin-bottom: 8px; }\n#tplRegOpContainer .resposta-opcoes label { display: flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 700; cursor: pointer; margin: 0; }\n#tplRegOpContainer .pops-checklist-wrap { max-height: 160px; overflow-y: auto; border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 8px; }\n#tplRegOpContainer .pops-checklist-wrap label { display: flex; gap: 6px; align-items: center; font-size: 12px; font-weight: 400; margin-bottom: 4px; cursor: pointer; }\n#tplRegOpContainer .checkbox-inline { display: flex; gap: 6px; align-items: center; font-size: 12px; font-weight: 700; cursor: pointer; margin: 10px 0; }\n#tplRegOpContainer .checkbox-inline input { cursor: pointer; }\n#tplRegOpContainer .ia-melhoria-wrap { margin-top: 8px; border: 1px solid var(--accent-2); border-radius: var(--radius-sm); padding: 10px 12px; background: var(--bc-info-bg); }\n#tplRegOpContainer .ia-melhoria-wrap .ia-original,\n#tplRegOpContainer .ia-melhoria-wrap .ia-sugestao { font-size: 12px; margin-bottom: 8px; white-space: pre-wrap; }\n#tplRegOpContainer .ia-melhoria-wrap .ia-label { font-size: 10.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .3px; color: var(--muted); display: block; margin-bottom: 3px; }\n#tplRegOpContainer .ia-melhoria-wrap .ia-sugestao { color: var(--text-strong); }\n#tplRegOpContainer .confirmar-exclusao-wrap { margin-top: 10px; border: 1px solid var(--danger); border-radius: var(--radius-sm); padding: 10px 12px; background: var(--bc-danger-bg); font-size: 12px; }\n#tplRegOpContainer .pendencia-item {\n  display: flex; align-items: center; gap: 10px; background: var(--surface-2); border: 1px solid var(--warning);\n  border-radius: var(--radius-sm); padding: 10px 12px; margin-bottom: 8px; flex-wrap: wrap;\n}\n#tplRegOpContainer .pendencia-item .pendencia-titulo { flex: 1; min-width: 200px; font-size: 12.5px; color: var(--text-strong); font-weight: 700; }\n#tplRegOpContainer .doc-item {\n  display: flex; align-items: center; gap: 10px; background: var(--surface-2); border: 1px solid var(--border);\n  border-radius: var(--radius-sm); padding: 10px 12px; margin-bottom: 8px; flex-wrap: wrap;\n}\n#tplRegOpContainer .doc-item .doc-titulo { flex: 1; min-width: 200px; font-size: 12.5px; color: var(--text-strong); font-weight: 700; }\n#tplRegOpContainer .terminal-wrap { margin-top: 12px; border-radius: var(--radius-sm); overflow: hidden; border: 1px solid var(--border); }\n#tplRegOpContainer .terminal-header { background: var(--bg); color: var(--muted); padding: 8px 12px; font-size: 10.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; border-bottom: 1px solid var(--border); }\n#tplRegOpContainer .terminal { background: var(--bg); color: var(--success); padding: 10px 12px; font-family: var(--bc-mono); font-size: 11.5px; max-height: 220px; overflow-y: auto; white-space: pre-wrap; }\n#tplRegOpContainer .terminal .erro { color: var(--danger); font-weight: 800; }\n#tplRegOpContainer .terminal .aviso { color: var(--warning); font-weight: 800; }\n#tplRegOpContainer .img-slot-list { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }\n#tplRegOpContainer .img-slot {\n  width: 110px; background: var(--card-soft); border: 1px solid var(--border); border-radius: 6px; padding: 6px;\n}\n#tplRegOpContainer .img-slot img { width: 100%; height: 64px; object-fit: cover; border-radius: 4px; margin-bottom: 4px; }\n#tplRegOpContainer .img-slot input { width: 100%; font-size: 10px; padding: 3px 5px; min-height: 22px; }\n#tplRegOpContainer .img-slot button { width: 100%; margin-top: 4px; }\n@media (max-width: 768px) {\n  #tplRegOpContainer .wrap { padding: 10px; }\n  #tplRegOpContainer .panel { padding: 14px; }\n  #tplRegOpContainer .step-nav-item { min-width: 90px; font-size: 10.5px; }\n}\n</style>\n\n<script>\n  const TPL_REGOP_HTML_ = `\n  <div id=\"tplRegOp_viewModulo\">\n  <div class=\"wrap\">\n    <header class=\"header-card\">\n      <div class=\"title-area\">\n        <h1 id=\"tplRegOp_appTitulo\">Registros Operacionais</h1>\n        <p>Preencha os registros de execução dos POPs (rondas, checklists, formulários, treinamentos e qualquer outro documento operacional) e mantenha a documentação em dia.</p>\n      </div>\n      <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_abrirManual_()\">Manual do Operador</button>\n    </header>\n\n    <div class=\"step-nav\">\n      <div class=\"step-nav-item active\" id=\"tplRegOp_nav1\">1. Cliente</div>\n      <div class=\"step-nav-item\" id=\"tplRegOp_nav2\">2. Tipo de Documento</div>\n      <div class=\"step-nav-item\" id=\"tplRegOp_nav3\">3. Preenchimento</div>\n      <div class=\"step-nav-item\" id=\"tplRegOp_nav4\">4. Consultar</div>\n    </div>\n\n    <div class=\"panel\">\n\n      <div class=\"step active\" id=\"tplRegOp_step1\">\n        <h2>1. Dados do cliente</h2>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>CNPJ</label>\n            <input id=\"tplRegOp_cnpj\" class=\"form-control\" placeholder=\"00.000.000/0000-00\">\n          </div>\n          <div class=\"form-group\" style=\"flex: 0 0 auto; align-self: flex-end;\">\n            <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_buscarCNPJ()\" id=\"tplRegOp_btnBuscarCnpj\">Buscar</button>\n          </div>\n        </div>\n        <div id=\"tplRegOp_alertaCnpj\"></div>\n        <div class=\"form-row\">\n          <div class=\"form-group w-100\">\n            <label>Razão social do cliente</label>\n            <input id=\"tplRegOp_hospital\" class=\"form-control\" placeholder=\"Razão social do cliente\">\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>Cidade</label>\n            <input id=\"tplRegOp_cidade\" class=\"form-control\">\n          </div>\n          <div class=\"form-group\">\n            <label>UF</label>\n            <input id=\"tplRegOp_uf\" class=\"form-control\" maxlength=\"2\">\n          </div>\n        </div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_abrirConsulta_()\">Consultar registros e pendências</button>\n          <button type=\"button\" class=\"btn btn-primary\" onclick=\"tplRegOp_irParaEtapa(2)\">Avançar</button>\n        </div>\n      </div>\n\n      <div class=\"step\" id=\"tplRegOp_step2\">\n        <h2>2. Tipo de Documento</h2>\n        <p style=\"color: var(--muted); font-size: 12.5px;\">Escolha um tipo de documento já criado ou crie um novo, com nome livre — pode estar ligado a nenhum, um ou vários POPs. Tipos novos ficam salvos e disponíveis pra qualquer hospital dali pra frente.</p>\n        <div class=\"form-row\">\n          <div class=\"form-group w-100\">\n            <label>Tipo de Documento</label>\n            <select id=\"tplRegOp_selectTipoDoc\" class=\"form-control\" onchange=\"tplRegOp_aoTrocarTipoDocumento_()\"></select>\n          </div>\n        </div>\n        <div id=\"tplRegOp_tipoDocResumoWrap\"></div>\n        <div id=\"tplRegOp_novoTipoFormWrap\"></div>\n        <div id=\"tplRegOp_camposEditWrap\"></div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_irParaEtapa(1)\">Voltar</button>\n          <button type=\"button\" class=\"btn btn-primary\" id=\"tplRegOp_btnAvancarPreenchimento\" onclick=\"tplRegOp_irParaPreenchimento_()\" disabled>Avançar</button>\n        </div>\n      </div>\n\n      <div class=\"step\" id=\"tplRegOp_step3\">\n        <h2>3. Preenchimento do Registro</h2>\n        <div id=\"tplRegOp_resumoTipoWrap\" style=\"color: var(--muted); font-size: 12.5px; margin-bottom: 14px;\"></div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>Data</label>\n            <input id=\"tplRegOp_data\" class=\"form-control\" placeholder=\"dd/mm/aaaa\">\n          </div>\n        </div>\n        <div id=\"tplRegOp_camposPreenchimentoWrap\"></div>\n        <div class=\"section-divider\">Observações Gerais (opcional)</div>\n        <div class=\"form-row\">\n          <div class=\"form-group w-100\">\n            <textarea id=\"tplRegOp_observacoesGerais\" class=\"form-control\" placeholder=\"Observações adicionais sobre esta execução...\"></textarea>\n          </div>\n        </div>\n        <div class=\"section-divider\">Fotos (opcional)</div>\n        <input type=\"file\" accept=\"image/*\" multiple onchange=\"tplRegOp_addImagens_(this)\">\n        <div id=\"tplRegOp_imagensWrap\"></div>\n        <div class=\"section-divider\">Assinaturas</div>\n        <div id=\"tplRegOp_assinaturasPreenchimentoWrap\"></div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_irParaEtapa(2)\">Voltar</button>\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_abrirConsulta_()\">Consultar registros e pendências</button>\n          <button type=\"button\" class=\"btn btn-primary\" id=\"tplRegOp_btnGerar\" onclick=\"tplRegOp_gerarRegistro()\">Gerar Registro</button>\n        </div>\n        <div id=\"tplRegOp_resultadoWrap\"></div>\n      </div>\n\n      <div class=\"step\" id=\"tplRegOp_step4\">\n        <h2>4. Consultar Registros Já Gerados</h2>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>CNPJ</label>\n            <input id=\"tplRegOp_cnpjConsulta\" class=\"form-control\" placeholder=\"00.000.000/0000-00\">\n          </div>\n          <div class=\"form-group\" style=\"flex: 0 0 auto; align-self: flex-end;\">\n            <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_consultarRegistros_()\">Buscar</button>\n          </div>\n        </div>\n        <div class=\"section-divider\">Pendências em Aberto</div>\n        <div id=\"tplRegOp_pendenciasWrap\"></div>\n        <div class=\"section-divider\">Histórico Completo</div>\n        <div id=\"tplRegOp_consultaWrap\"></div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_irParaEtapa(1)\">Voltar ao início</button>\n        </div>\n      </div>\n\n      <div class=\"section-divider\">Histórico da operação</div>\n      <div class=\"terminal-wrap\">\n        <div class=\"terminal-header\">Histórico da operação (visível em todas as etapas)</div>\n        <div class=\"terminal\" id=\"tplRegOp_terminalLog\">Aguardando...</div>\n      </div>\n      <div class=\"btn-container\">\n        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_limparLog()\">Limpar histórico</button>\n      </div>\n\n    </div>\n  </div>\n  </div>\n\n  <div id=\"tplRegOp_viewManual\" style=\"display:none\">\n  <div class=\"wrap manual-wrap\">\n\n    <header class=\"header-card\" style=\"position:static; margin-bottom:24px;\">\n      <div class=\"title-area\">\n        <h1 style=\"margin-bottom:4px;\">Manual do Operador</h1>\n        <p style=\"margin:0;\">Registros Operacionais — preenchimento e controle de documentos operacionais (rondas, checklists, formulários, treinamentos)</p>\n      </div>\n      <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_voltarDoManual_()\">← Voltar ao sistema</button>\n    </header>\n\n    <div class=\"toc\" id=\"tplRegOp_topoManual\">\n      <h2>Índice</h2>\n      <ol>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms1')\">Como usar este manual</a></li>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms2')\">O que este sistema faz</a></li>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms3')\">Etapa 1 — Dados do cliente</a></li>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms4')\">Etapa 2 — Tipo de Documento</a></li>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms5')\">Etapa 3 — Preenchimento do Registro</a></li>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms6')\">Etapa 4 — Consultar Registros</a></li>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms7')\">Pendências em aberto</a></li>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms8')\">Passo a passo completo</a></li>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms9')\">Erros comuns</a></li>\n        <li><a onclick=\"tplRegOp_irParaSecao_('tplRegOp_ms10')\">Glossário</a></li>\n      </ol>\n    </div>\n\n    <h2 id=\"tplRegOp_ms1\">1. Como usar este manual</h2>\n    <p>Este manual foi escrito para quem <strong>nunca usou o sistema</strong>. Leia na ordem, de cima para baixo, seguindo a tela também de cima para baixo. Se aparecer uma palavra técnica desconhecida, vá direto ao <strong>Glossário</strong> (seção 10).</p>\n\n    <h2 id=\"tplRegOp_ms2\">2. O que este sistema faz, em uma frase</h2>\n    <p>Você registra a execução de qualquer documento operacional do hospital (ronda, checklist, formulário, treinamento, etc.) — o sistema guarda tudo organizado por hospital e por tipo de documento, e avisa quando algum registro ficou <strong>pendente</strong> (aberto, esperando um documento que o feche).</p>\n    <div class=\"callout\"><strong>\"Tipo de Documento\" é flexível.</strong> Você não está preso a uma lista fixa — pode criar, editar e excluir os tipos de documento que o hospital precisa, cada um com seus próprios campos.</div>\n\n    <h2 id=\"tplRegOp_ms3\">3. Etapa 1 — Dados do cliente</h2>\n    <table>\n      <tr><th>Campo</th><th>O que fazer</th></tr>\n      <tr><td>CNPJ</td><td>Digite e clique em \"Buscar\" — preenche Razão Social, Cidade e UF sozinho</td></tr>\n    </table>\n    <p>Clique em <strong>\"Avançar\"</strong> pra ir pra etapa 2.</p>\n\n    <h2 id=\"tplRegOp_ms4\">4. Etapa 2 — Tipo de Documento</h2>\n    <p>Escolha o tipo de documento que você vai registrar. Se o tipo que você precisa não existe ainda, escolha <strong>\"+ Criar novo tipo de documento\"</strong> na lista e preencha:</p>\n    <table>\n      <tr><th>Campo</th><th>O que fazer</th></tr>\n      <tr><td>Nome do tipo de documento</td><td>Ex.: \"Checklist de Ronda Noturna\", \"Ata de Treinamento\"</td></tr>\n      <tr><td>POP(s) relacionado(s) (opcional)</td><td>Se esse documento existe pra comprovar a execução de um POP específico, relacione aqui</td></tr>\n      <tr><td>Documento que fecha esta pendência</td><td>Marque se esse tipo de documento, quando gerado, deve ficar como \"pendente\" até outro documento futuro fechar essa pendência (ex.: uma não-conformidade aberta que só fecha quando a correção for registrada)</td></tr>\n    </table>\n    <p>Clique em <strong>\"Gerar sugestão de campos com IA\"</strong> pra deixar a Inteligência Artificial sugerir quais campos esse tipo de documento normalmente precisa — você pode aceitar, editar ou remover qualquer campo sugerido. Se preferir (ou se a IA não estiver disponível), clique em <strong>\"Montar os campos manualmente\"</strong>. Use <strong>\"+ Adicionar campo\"</strong> e <strong>\"+ Adicionar assinatura\"</strong> pra montar manualmente. No fim, clique em <strong>\"Salvar tipo de documento\"</strong>: o tipo fica disponível para todos os clientes. Um tipo já criado pode ser mudado depois com <strong>\"Editar este tipo\"</strong>, ou removido com <strong>\"Excluir este tipo\"</strong> (pede confirmação).</p>\n\n    <h2 id=\"tplRegOp_ms5\">5. Etapa 3 — Preenchimento do Registro</h2>\n    <p>Preencha os campos definidos pro tipo de documento escolhido (variam conforme o tipo). Em qualquer campo de texto, o botão <strong>\"Revisar texto (IA)\"</strong> reescreve o que você digitou de forma mais clara e profissional — você decide entre <strong>\"Usar sugestão da IA\"</strong> ou <strong>\"Manter o que escrevi\"</strong>, a IA nunca troca o texto sozinha sem sua confirmação. Anexe imagens se o tipo de documento permitir. Clique em <strong>\"Gerar Registro\"</strong> pra finalizar.</p>\n\n    <h2 id=\"tplRegOp_ms6\">6. Etapa 4 — Consultar Registros Já Gerados</h2>\n    <p>Na etapa 1 (ou na etapa 3), clique em <strong>\"Consultar registros e pendências\"</strong>. Se o CNPJ já estiver preenchido, a consulta sai na hora; senão, digite o CNPJ e clique em \"Buscar\" pra ver o <strong>Histórico Completo</strong> de registros desse hospital.</p>\n\n    <h2 id=\"tplRegOp_ms7\">7. Pendências em aberto</h2>\n    <p>Na mesma etapa de consulta, a seção \"Pendências em Aberto\" mostra registros que ainda não foram fechados — cada um mostra a data em que ficou pendente. Pra fechar, clique em <strong>\"Registrar Fechamento\"</strong> na pendência correspondente — isso abre um novo preenchimento já vinculado àquela pendência.</p>\n\n    <h2 id=\"tplRegOp_ms8\">8. Passo a passo completo</h2>\n    <ol>\n      <li>Etapa 1: CNPJ, buscar, conferir dados do hospital.</li>\n      <li>Etapa 2: escolher ou criar o tipo de documento.</li>\n      <li>Etapa 3: preencher os campos, usar \"Revisar texto (IA)\" se quiser, gerar o registro.</li>\n      <li>Etapa 4: consultar histórico e pendências em aberto quando precisar.</li>\n    </ol>\n\n    <h2 id=\"tplRegOp_ms9\">9. Erros comuns e o que fazer</h2>\n    <table>\n      <tr><th>O que aconteceu</th><th>O que fazer</th></tr>\n      <tr><td>O botão \"Avançar\" da etapa 2 está desabilitado</td><td>Escolha ou finalize a criação de um tipo de documento antes de avançar</td></tr>\n      <tr><td>Não sei quais campos colocar num tipo novo</td><td>Use \"Gerar sugestão de campos com IA\" como ponto de partida</td></tr>\n      <tr><td>Um registro sumiu da lista de pendências</td><td>Provavelmente já foi fechado — confira no Histórico Completo</td></tr>\n      <tr><td>\"A interpretação por IA não está disponível\"</td><td>A chave da IA não está cadastrada no sistema. Peça ao administrador para cadastrá-la em Chaves e senhas. Enquanto isso, use \"Montar os campos manualmente\" e escreva os textos sem a revisão da IA</td></tr>\n      <tr><td>\"A data do registro ... não é uma data válida\"</td><td>Corrija o campo \"Data\" da etapa 3 no formato dd/mm/aaaa (ex.: 16/10/2026)</td></tr>\n    </table>\n\n    <h2 id=\"tplRegOp_ms10\">10. Glossário</h2>\n    <table>\n      <tr><th>Termo</th><th>Explicação simples</th></tr>\n      <tr><td>Tipo de Documento</td><td>Um modelo reutilizável, com campos próprios, pra um tipo de registro operacional</td></tr>\n      <tr><td>Pendência</td><td>Um registro que ficou \"em aberto\", esperando um documento futuro que o feche</td></tr>\n      <tr><td>Registrar Fechamento</td><td>Preencher o documento que fecha uma pendência específica</td></tr>\n      <tr><td>POP</td><td>Procedimento Operacional Padrão que esse registro comprova ter sido executado</td></tr>\n    </table>\n\n    <a class=\"topo-link\" onclick=\"tplRegOp_irParaSecao_('tplRegOp_topoManual')\">↑ Topo</a>\n  </div>\n  </div>\n  `;\n\n  function tplRegOp_abrirManual_() {\n    const viewModulo = document.getElementById('tplRegOp_viewModulo');\n    const viewManual = document.getElementById('tplRegOp_viewManual');\n    if (viewModulo) viewModulo.style.display = 'none';\n    if (viewManual) viewManual.style.display = '';\n  }\n\n  function tplRegOp_voltarDoManual_() {\n    const viewModulo = document.getElementById('tplRegOp_viewModulo');\n    const viewManual = document.getElementById('tplRegOp_viewManual');\n    if (viewManual) viewManual.style.display = 'none';\n    if (viewModulo) viewModulo.style.display = '';\n  }\n\n  function tplRegOp_irParaSecao_(id) {\n    const el = document.getElementById(id);\n    if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });\n  }\n\n  // ============================================================\n  // ESTADO\n  // ============================================================\n  let tplRegOp_bootstrap_ = null;\n  let tplRegOp_tiposDocumento_ = []; // [{id, nome, popsRelacionados, campos, assinaturas, abrePendencia, tipoFechamentoId}] -- todos os tipos já criados\n  let tplRegOp_tipoDocumentoAtual_ = null; // tipo escolhido/salvo nesta sessão de preenchimento\n  let tplRegOp_camposEmEdicao_ = []; // [{id, rotulo, tipo, secao, usarIA}] -- durante criação/edição de um tipo\n  let tplRegOp_assinaturasEmEdicao_ = []; // [{id, papel}] -- durante criação/edição de um tipo\n  let tplRegOp_novoTipoContexto_ = null; // {id, nome, pops, abrePendencia, tipoFechamentoId} do tipo em criação/edição (id presente = editando)\n  let tplRegOp_imagens_ = []; // [{base64, mimeType, legenda}]\n  let tplRegOp_fechandoPendenciaId_ = null; // ID do registro de origem, quando o preenchimento atual é um fechamento de pendência\n  let tplRegOp_exclusaoPendente_ = null; // {id} do tipo aguardando confirmação de exclusão\n\n  function tplRegOp_el(id) { return document.getElementById(id); }\n\n  function tplRegOp_dispatch_(fn, payload) {\n    return new Promise((resolve, reject) => {\n      SGO_iniciarCarregamento_();\n      google.script.run\n        .withSuccessHandler(function(res) { SGO_finalizarCarregamento_(); resolve(res); })\n        .withFailureHandler(function(err) { SGO_finalizarCarregamento_(); reject(err); })\n        .RegOp_apiDispatch({ sessionId: SGO_getSessionId(), fn: fn, payload: payload || {} });\n    });\n  }\n\n  function tplRegOp_escapeHtml_(v) {\n    return String(v == null ? '' : v)\n      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')\n      .replace(/\"/g, '&quot;').replace(/'/g, '&#39;');\n  }\n\n  function tplRegOp_gerarIdLocal_() {\n    return 'it_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);\n  }\n\n  // ============================================================\n  // CONSOLE OPERACIONAL\n  // ============================================================\n  function tplRegOp_writeLog(msg, tipo) {\n    const term = tplRegOp_el('tplRegOp_terminalLog');\n    if (!term) return;\n    const cls = tipo === 'ERRO' ? 'erro' : (tipo === 'AVISO' ? 'aviso' : '');\n    const linha = document.createElement('div');\n    if (cls) linha.className = cls;\n    linha.textContent = '[' + new Date().toLocaleTimeString('pt-BR') + '] ' + msg;\n    term.appendChild(linha);\n    term.scrollTop = term.scrollHeight;\n  }\n\n  function tplRegOp_limparLog() {\n    const term = tplRegOp_el('tplRegOp_terminalLog');\n    if (term) term.innerHTML = '';\n    tplRegOp_writeLog('Histórico limpo.');\n  }\n\n  function tplRegOp_verificarResposta_(r, contexto) {\n    if (!r) {\n      const msg = 'O servidor não respondeu à operação \"' + contexto + '\" (resposta vazia/nula). Recarregue a página (F5) e tente de novo — se persistir, avise o suporte com o horário e os dados usados.';\n      tplRegOp_writeLog(msg, 'ERRO');\n      throw new Error(msg);\n    }\n    return r;\n  }\n\n  // ============================================================\n  // NAVEGAÇÃO\n  // ============================================================\n  function tplRegOp_irParaEtapa(n) {\n    for (let i = 1; i <= 4; i++) {\n      const step = tplRegOp_el('tplRegOp_step' + i);\n      const nav = tplRegOp_el('tplRegOp_nav' + i);\n      if (step) step.classList.toggle('active', i === n);\n      if (nav) {\n        nav.classList.toggle('active', i === n);\n        nav.classList.toggle('done', i < n);\n      }\n    }\n  }\n\n  // ============================================================\n  // INICIALIZAÇÃO\n  // ============================================================\n  function tplRegOp_inicializar() {\n    \n    SGO_iniciarCarregamento_();\n    google.script.run\n      .withSuccessHandler(function (boot) {\n        SGO_finalizarCarregamento_();\n        if (!boot) {\n          tplRegOp_writeLog('Conexão inicial não retornou dados (resposta vazia). Recarregue a página.', 'ERRO');\n          return;\n        }\n        tplRegOp_bootstrap_ = boot;\n        const titulo = tplRegOp_el('tplRegOp_appTitulo');\n        if (titulo && boot.appNome) titulo.textContent = String(boot.appNome).replace(/^METROLABS\\s*[•-]\\s*/i, '');\n        const dataEl = tplRegOp_el('tplRegOp_data');\n        if (dataEl && !dataEl.value) {\n          const hoje = new Date();\n          dataEl.value = String(hoje.getDate()).padStart(2, '0') + '/' + String(hoje.getMonth() + 1).padStart(2, '0') + '/' + hoje.getFullYear();\n        }\n        \n        tplRegOp_carregarTiposDocumento_();\n      })\n      .withFailureHandler(function (err) {\n        SGO_finalizarCarregamento_();\n        console.error('tplRegOp_inicializar falhou:', err);\n        tplRegOp_writeLog('Não foi possível carregar a configuração: ' + (err && err.message ? err.message : err) + '. Recarregue a página (F5).', 'ERRO');\n      })\n      .RegOp_getAppBootstrap();\n  }\n\n  // ============================================================\n  // PASSO 1 — CNPJ\n  // ============================================================\n  async function tplRegOp_buscarCNPJ() {\n    const cnpj = tplRegOp_el('tplRegOp_cnpj').value;\n    const alerta = tplRegOp_el('tplRegOp_alertaCnpj');\n    const btn = tplRegOp_el('tplRegOp_btnBuscarCnpj');\n    alerta.innerHTML = '';\n    btn.disabled = true;\n    btn.textContent = 'Buscando...';\n    tplRegOp_writeLog('Consultando CNPJ ' + cnpj + ' em base pública...');\n    try {\n      const r = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiConsultarCnpj', { cnpj: cnpj }), 'buscar CNPJ');\n      tplRegOp_el('tplRegOp_cnpj').value = r.cnpj || cnpj;\n      tplRegOp_el('tplRegOp_hospital').value = r.razaoSocial || r.cliente || '';\n      tplRegOp_el('tplRegOp_cidade').value = r.municipio || '';\n      tplRegOp_el('tplRegOp_uf').value = r.uf || '';\n      alerta.innerHTML = '<div class=\"alert-box success\">CNPJ encontrado (' + tplRegOp_escapeHtml_(r.fonte || '') + ').</div>';\n      tplRegOp_writeLog('CNPJ encontrado: ' + (r.razaoSocial || r.cliente || '-'), 'SUCESSO');\n    } catch (e) {\n      const msg = String(e && e.message ? e.message : e).replace(/^Error:\\s*/i, '').trim();\n      alerta.innerHTML = '<div class=\"alert-box warning\">Não foi possível buscar automaticamente: ' + tplRegOp_escapeHtml_(msg) + (/preencha manualmente/i.test(msg) ? '' : (/[.!?]$/.test(msg) ? ' ' : '. ') + 'Preencha manualmente.') + '</div>';\n      tplRegOp_writeLog('Falha ao buscar CNPJ: ' + msg, 'ERRO');\n    } finally {\n      btn.disabled = false;\n      btn.textContent = 'Buscar';\n    }\n  }\n\n  function tplRegOp_obterHospital_() {\n    return {\n      razaoSocial: tplRegOp_el('tplRegOp_hospital').value,\n      cnpj: tplRegOp_el('tplRegOp_cnpj').value,\n      cidade: tplRegOp_el('tplRegOp_cidade').value,\n      uf: tplRegOp_el('tplRegOp_uf').value\n    };\n  }\n\n  // ============================================================\n  // PASSO 2 — TIPO DE DOCUMENTO (livre, N:N com POPs)\n  // ============================================================\n  async function tplRegOp_carregarTiposDocumento_() {\n    try {\n      const r = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiListarTiposDocumento', {}), 'listar tipos de documento');\n      tplRegOp_tiposDocumento_ = (r.ok && r.tipos) ? r.tipos : [];\n      if (!r.ok) tplRegOp_writeLog('Falha ao listar tipos de documento: ' + r.mensagem, 'ERRO');\n    } catch (e) {\n      tplRegOp_writeLog('Erro ao carregar tipos de documento: ' + (e && e.message ? e.message : e), 'ERRO');\n      tplRegOp_tiposDocumento_ = [];\n    }\n    tplRegOp_renderSelectTipoDocumento_();\n  }\n\n  function tplRegOp_renderSelectTipoDocumento_() {\n    const sel = tplRegOp_el('tplRegOp_selectTipoDoc');\n    if (!sel) return;\n    const valorAtual = sel.value;\n    const ordenados = tplRegOp_tiposDocumento_.slice().sort((a, b) => a.nome < b.nome ? -1 : (a.nome > b.nome ? 1 : 0));\n    sel.innerHTML = '<option value=\"\">Selecione...</option>' +\n      '<option value=\"__novo__\">+ Criar novo tipo de documento</option>' +\n      ordenados.map(t => `<option value=\"${tplRegOp_escapeHtml_(t.id)}\">${tplRegOp_escapeHtml_(t.nome)}</option>`).join('');\n    const opt = Array.from(sel.options).find(o => o.value === valorAtual);\n    if (opt) sel.value = valorAtual;\n  }\n\n  function tplRegOp_aoTrocarTipoDocumento_() {\n    const sel = tplRegOp_el('tplRegOp_selectTipoDoc');\n    const valor = sel.value;\n    tplRegOp_el('tplRegOp_tipoDocResumoWrap').innerHTML = '';\n    tplRegOp_el('tplRegOp_novoTipoFormWrap').innerHTML = '';\n    tplRegOp_el('tplRegOp_camposEditWrap').innerHTML = '';\n    tplRegOp_el('tplRegOp_btnAvancarPreenchimento').disabled = true;\n    tplRegOp_tipoDocumentoAtual_ = null;\n    tplRegOp_novoTipoContexto_ = null;\n    tplRegOp_exclusaoPendente_ = null;\n    if (!valor) return;\n    if (valor === '__novo__') {\n      tplRegOp_mostrarFormTipo_(null);\n      return;\n    }\n    const tipo = tplRegOp_tiposDocumento_.find(t => t.id === valor);\n    if (!tipo) return;\n    tplRegOp_tipoDocumentoAtual_ = tipo;\n    tplRegOp_renderResumoTipo_(tipo);\n    tplRegOp_el('tplRegOp_btnAvancarPreenchimento').disabled = false;\n  }\n\n  function tplRegOp_renderResumoTipo_(tipo) {\n    tplRegOp_el('tplRegOp_tipoDocResumoWrap').innerHTML =\n      '<div class=\"alert-box success\">\"' + tplRegOp_escapeHtml_(tipo.nome) + '\" — ' + tipo.campos.length +\n      ' campo(s), assinatura(s): ' + tplRegOp_escapeHtml_((tipo.assinaturas || []).join(', ')) + '</div>' +\n      '<div class=\"btn-container\">' +\n      '<button type=\"button\" class=\"btn btn-secondary btn-xs\" onclick=\"tplRegOp_editarTipoAtual_()\">Editar este tipo</button>' +\n      '<button type=\"button\" class=\"btn btn-danger btn-xs\" onclick=\"tplRegOp_excluirTipoAtual_()\">Excluir este tipo</button>' +\n      '</div>' +\n      '<div id=\"tplRegOp_exclusaoWrap\"></div>';\n  }\n\n  function tplRegOp_editarTipoAtual_() {\n    const tipo = tplRegOp_tipoDocumentoAtual_;\n    if (!tipo) return;\n    tplRegOp_mostrarFormTipo_(tipo);\n    tplRegOp_camposEmEdicao_ = (tipo.campos || []).map(c => ({ id: tplRegOp_gerarIdLocal_(), rotulo: c.rotulo, tipo: c.tipo || 'texto', secao: c.secao || '', usarIA: !!c.usarIA }));\n    tplRegOp_assinaturasEmEdicao_ = (tipo.assinaturas || []).map(a => ({ id: tplRegOp_gerarIdLocal_(), papel: a }));\n    tplRegOp_desenharCamposEditaveis_();\n  }\n\n  async function tplRegOp_excluirTipoAtual_() {\n    const tipo = tplRegOp_tipoDocumentoAtual_;\n    if (!tipo) return;\n    const wrap = tplRegOp_el('tplRegOp_exclusaoWrap');\n    if (!tplRegOp_exclusaoPendente_ || tplRegOp_exclusaoPendente_.id !== tipo.id) {\n      wrap.innerHTML = '<div class=\"alert-box info\">Verificando uso deste tipo...</div>';\n      try {\n        const r = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiExcluirTipoDocumento', { id: tipo.id }), 'verificar exclusão');\n        if (!r.ok) { wrap.innerHTML = '<div class=\"alert-box error\">' + tplRegOp_escapeHtml_(r.mensagem) + '</div>'; return; }\n        tplRegOp_exclusaoPendente_ = { id: tipo.id };\n        const usadoComoFechamento = tplRegOp_tiposDocumento_.filter(t => t.tipoFechamentoId === tipo.id).map(t => t.nome);\n        const aviso = (r.totalRegistros > 0\n          ? ('Este tipo já foi usado em ' + r.totalRegistros + ' registro(s) gerado(s) — eles continuam intactos, mas o tipo some da lista pra novos preenchimentos.')\n          : 'Este tipo ainda não foi usado em nenhum registro.') +\n          (usadoComoFechamento.length ? (' Atenção: ele é o documento de fechamento de \"' + usadoComoFechamento.join('\", \"') + '\"; depois de excluir, edite esse(s) tipo(s) e escolha outro documento de fechamento.') : '');\n        wrap.innerHTML = '<div class=\"confirmar-exclusao-wrap\">' + tplRegOp_escapeHtml_(aviso) +\n          ' Tem certeza que quer excluir \"' + tplRegOp_escapeHtml_(tipo.nome) + '\"?' +\n          '<div class=\"btn-container\"><button type=\"button\" class=\"btn btn-danger btn-xs\" onclick=\"tplRegOp_excluirTipoAtual_()\">Sim, excluir mesmo assim</button></div></div>';\n      } catch (e) {\n        wrap.innerHTML = '<div class=\"alert-box error\">Erro: ' + tplRegOp_escapeHtml_(e && e.message ? e.message : e) + '</div>';\n      }\n      return;\n    }\n    tplRegOp_writeLog('Excluindo tipo de documento \"' + tipo.nome + '\"...');\n    try {\n      const r = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiExcluirTipoDocumento', { id: tipo.id, confirmado: true }), 'excluir tipo de documento');\n      if (!r.ok) {\n        tplRegOp_writeLog('Falha ao excluir: ' + r.mensagem, 'ERRO');\n        wrap.innerHTML = '<div class=\"alert-box error\">' + tplRegOp_escapeHtml_(r.mensagem) + '</div>';\n        return;\n      }\n      tplRegOp_tiposDocumento_ = tplRegOp_tiposDocumento_.filter(t => t.id !== tipo.id);\n      tplRegOp_exclusaoPendente_ = null;\n      tplRegOp_renderSelectTipoDocumento_();\n      tplRegOp_el('tplRegOp_selectTipoDoc').value = '';\n      tplRegOp_aoTrocarTipoDocumento_();\n      tplRegOp_writeLog('Tipo de documento excluído.', 'SUCESSO');\n    } catch (e) {\n      tplRegOp_writeLog('Erro ao excluir tipo de documento: ' + (e && e.message ? e.message : e), 'ERRO');\n    }\n  }\n\n  function tplRegOp_mostrarFormTipo_(tipoExistente) {\n    const wrap = tplRegOp_el('tplRegOp_novoTipoFormWrap');\n    const catalogo = (tplRegOp_bootstrap_ && tplRegOp_bootstrap_.catalogoPops) || [];\n    const popsSelecionados = tipoExistente ? (tipoExistente.popsRelacionados || []).map(p => p.codigo) : [];\n    wrap.innerHTML = `\n      <div class=\"section-divider\">${tipoExistente ? 'Editar Tipo de Documento' : 'Novo Tipo de Documento'}</div>\n      <div class=\"form-row\">\n        <div class=\"form-group w-100\">\n          <label>Nome do tipo de documento</label>\n          <input type=\"text\" id=\"tplRegOp_novoTipoNome\" class=\"form-control\" placeholder=\"Ex.: Saída de Equipamento para Assistência Técnica Externa\" value=\"${tplRegOp_escapeHtml_(tipoExistente ? tipoExistente.nome : '')}\">\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group w-100\">\n          <label>POP(s) relacionado(s) (opcional)</label>\n          <div id=\"tplRegOp_novoTipoPopsWrap\" class=\"pops-checklist-wrap\">\n            ${catalogo.map(p => `<label><input type=\"checkbox\" value=\"${tplRegOp_escapeHtml_(p.codigo)}\" data-nome=\"${tplRegOp_escapeHtml_(p.nome)}\" ${popsSelecionados.includes(p.codigo) ? 'checked' : ''}> ${tplRegOp_escapeHtml_(p.codigo)} — ${tplRegOp_escapeHtml_(p.nome)}</label>`).join('')}\n          </div>\n        </div>\n      </div>\n      ${tipoExistente ? '' : `\n      <div class=\"form-row\">\n        <div class=\"form-group w-100\">\n          <label>Roteiro / contexto (opcional)</label>\n          <textarea id=\"tplRegOp_novoTipoRoteiro\" class=\"form-control\" placeholder=\"Descreva o que este documento precisa registrar, se quiser orientar a IA...\"></textarea>\n        </div>\n      </div>\n      <div class=\"btn-container\">\n        <button type=\"button\" class=\"btn btn-primary\" id=\"tplRegOp_btnSugerirCampos\" onclick=\"tplRegOp_sugerirCamposDocumento_()\">Gerar sugestão de campos com IA</button>\n        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplRegOp_montarCamposManual_()\">Montar os campos manualmente</button>\n      </div>\n      `}\n    `;\n    if (tipoExistente) {\n      tplRegOp_novoTipoContexto_ = {\n        id: tipoExistente.id,\n        nome: tipoExistente.nome,\n        pops: tipoExistente.popsRelacionados || [],\n        abrePendencia: !!tipoExistente.abrePendencia,\n        tipoFechamentoId: tipoExistente.tipoFechamentoId || ''\n      };\n    }\n  }\n\n  async function tplRegOp_sugerirCamposDocumento_() {\n    const nome = tplRegOp_el('tplRegOp_novoTipoNome').value.trim();\n    if (!nome) {\n      tplRegOp_writeLog('Informe o nome do tipo de documento antes de gerar a sugestão.', 'AVISO');\n      return;\n    }\n    const pops = Array.from(document.querySelectorAll('#tplRegOp_novoTipoPopsWrap input:checked')).map(cb => ({ codigo: cb.value, nome: cb.dataset.nome }));\n    const roteiro = tplRegOp_el('tplRegOp_novoTipoRoteiro').value;\n    const btn = tplRegOp_el('tplRegOp_btnSugerirCampos');\n    btn.disabled = true;\n    btn.textContent = 'Gerando sugestão...';\n    tplRegOp_writeLog('Gerando sugestão de campos com IA pra \"' + nome + '\"...');\n    try {\n      const r = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiSugerirCamposDocumento', { nomeDocumento: nome, popsRelacionados: pops, roteiro: roteiro }), 'sugerir campos');\n      if (!r.ok) {\n        tplRegOp_writeLog('Falha ao sugerir campos: ' + r.mensagem, 'ERRO');\n        return;\n      }\n      tplRegOp_writeLog(r.campos.length + ' campo(s) e ' + r.assinaturas.length + ' assinatura(s) sugerido(s) pela IA. Revise antes de salvar.', 'SUCESSO');\n      tplRegOp_camposEmEdicao_ = r.campos.map(c => ({ id: tplRegOp_gerarIdLocal_(), rotulo: c.rotulo, tipo: c.tipo || 'texto', secao: c.secao || '', usarIA: false }));\n      tplRegOp_assinaturasEmEdicao_ = r.assinaturas.map(a => ({ id: tplRegOp_gerarIdLocal_(), papel: a }));\n      tplRegOp_novoTipoContexto_ = { nome: nome, pops: pops, abrePendencia: false, tipoFechamentoId: '' };\n      tplRegOp_desenharCamposEditaveis_();\n    } catch (e) {\n      tplRegOp_writeLog('Erro ao sugerir campos: ' + (e && e.message ? e.message : e), 'ERRO');\n    } finally {\n      btn.disabled = false;\n      btn.textContent = 'Gerar sugestão de campos com IA';\n    }\n  }\n\n  function tplRegOp_montarCamposManual_() {\n    const nome = tplRegOp_el('tplRegOp_novoTipoNome').value.trim();\n    if (!nome) {\n      tplRegOp_writeLog('Informe o nome do tipo de documento antes de montar os campos.', 'AVISO');\n      return;\n    }\n    const pops = Array.from(document.querySelectorAll('#tplRegOp_novoTipoPopsWrap input:checked')).map(cb => ({ codigo: cb.value, nome: cb.dataset.nome }));\n    if (!tplRegOp_camposEmEdicao_.length || !tplRegOp_novoTipoContexto_) {\n      tplRegOp_camposEmEdicao_ = [{ id: tplRegOp_gerarIdLocal_(), rotulo: '', tipo: 'texto', secao: '', usarIA: false }];\n      tplRegOp_assinaturasEmEdicao_ = [{ id: tplRegOp_gerarIdLocal_(), papel: 'Responsável pelo Registro' }];\n    }\n    tplRegOp_novoTipoContexto_ = { nome: nome, pops: pops, abrePendencia: false, tipoFechamentoId: '' };\n    tplRegOp_desenharCamposEditaveis_();\n    tplRegOp_writeLog('Monte os campos abaixo (rótulo, tipo e seção) e clique em \"Salvar tipo de documento\".');\n  }\n\n  function tplRegOp_desenharCamposEditaveis_() {\n    const wrap = tplRegOp_el('tplRegOp_camposEditWrap');\n    const tipos = { sim_nao_na: 'Sim/Não/N-A', texto: 'Texto livre', numero: 'Número', data: 'Data' };\n    const outrosTipos = tplRegOp_tiposDocumento_.filter(t => t.id !== (tplRegOp_novoTipoContexto_ && tplRegOp_novoTipoContexto_.id));\n    const ctx = tplRegOp_novoTipoContexto_ || {};\n    wrap.innerHTML = '<div class=\"section-divider\">Campos do Documento (edite se quiser)</div>' +\n      tplRegOp_camposEmEdicao_.map(c => `\n        <div class=\"item-checklist\">\n          <div class=\"item-checklist-edit\">\n            <input type=\"text\" value=\"${tplRegOp_escapeHtml_(c.rotulo)}\" placeholder=\"Rótulo do campo\" onchange=\"tplRegOp_atualizarCampoEdicao_('${c.id}', 'rotulo', this.value)\">\n            <select onchange=\"tplRegOp_atualizarTipoCampoEdicao_('${c.id}', this.value)\">\n              ${Object.keys(tipos).map(t => `<option value=\"${t}\" ${t === c.tipo ? 'selected' : ''}>${tipos[t]}</option>`).join('')}\n            </select>\n            <input type=\"text\" value=\"${tplRegOp_escapeHtml_(c.secao)}\" placeholder=\"Seção (opcional)\" onchange=\"tplRegOp_atualizarCampoEdicao_('${c.id}', 'secao', this.value)\">\n            <button type=\"button\" class=\"btn btn-danger btn-xs\" onclick=\"tplRegOp_removerCampoEdicao_('${c.id}')\">Remover</button>\n          </div>\n          ${c.tipo === 'texto' ? `\n          <label class=\"checkbox-inline\"><input type=\"checkbox\" ${c.usarIA ? 'checked' : ''} onchange=\"tplRegOp_atualizarCampoEdicao_('${c.id}', 'usarIA', this.checked)\"> A IA revisa o texto digitado (o colaborador vê e decide se aceita)</label>\n          ` : ''}\n        </div>\n      `).join('') +\n      '<div class=\"btn-container\"><button type=\"button\" class=\"btn btn-secondary btn-xs\" onclick=\"tplRegOp_adicionarCampoEdicao_()\">+ Adicionar campo</button></div>' +\n      '<div class=\"section-divider\">Assinaturas Necessárias</div>' +\n      tplRegOp_assinaturasEmEdicao_.map(a => `\n        <div class=\"item-checklist\">\n          <div class=\"item-checklist-edit\">\n            <input type=\"text\" value=\"${tplRegOp_escapeHtml_(a.papel)}\" placeholder=\"Papel (ex.: Responsável pelo Registro)\" onchange=\"tplRegOp_atualizarAssinaturaEdicao_('${a.id}', this.value)\">\n            <button type=\"button\" class=\"btn btn-danger btn-xs\" onclick=\"tplRegOp_removerAssinaturaEdicao_('${a.id}')\">Remover</button>\n          </div>\n        </div>\n      `).join('') +\n      '<div class=\"btn-container\"><button type=\"button\" class=\"btn btn-secondary btn-xs\" onclick=\"tplRegOp_adicionarAssinaturaEdicao_()\">+ Adicionar assinatura</button></div>' +\n      '<div class=\"section-divider\">Pendência</div>' +\n      `<label class=\"checkbox-inline\"><input type=\"checkbox\" id=\"tplRegOp_abrePendencia\" ${ctx.abrePendencia ? 'checked' : ''} onchange=\"tplRegOp_atualizarAbrePendencia_(this.checked)\"> Este documento abre uma pendência (precisa de um documento de fechamento depois)</label>` +\n      `<div id=\"tplRegOp_tipoFechamentoWrap\" style=\"${ctx.abrePendencia ? '' : 'display:none;'}\">` +\n      `<div class=\"form-row\"><div class=\"form-group w-100\"><label>Documento que fecha esta pendência</label>` +\n      `<select class=\"form-control\" onchange=\"tplRegOp_atualizarTipoFechamento_(this.value)\">` +\n      `<option value=\"\">Selecione depois (editar este tipo mais tarde)...</option>` +\n      outrosTipos.map(t => `<option value=\"${tplRegOp_escapeHtml_(t.id)}\" ${t.id === ctx.tipoFechamentoId ? 'selected' : ''}>${tplRegOp_escapeHtml_(t.nome)}</option>`).join('') +\n      `</select></div></div></div>` +\n      '<div class=\"btn-container\">' +\n      '<button type=\"button\" class=\"btn btn-primary\" onclick=\"tplRegOp_salvarTipoDocumento_()\">' + (ctx.id ? 'Salvar alterações' : 'Salvar tipo de documento') + '</button>' +\n      '</div>';\n  }\n\n  function tplRegOp_atualizarCampoEdicao_(id, campo, valor) {\n    const item = tplRegOp_camposEmEdicao_.find(c => c.id === id);\n    if (item) item[campo] = valor;\n  }\n  function tplRegOp_atualizarTipoCampoEdicao_(id, valor) {\n    const item = tplRegOp_camposEmEdicao_.find(c => c.id === id);\n    if (item) { item.tipo = valor; if (valor !== 'texto') item.usarIA = false; }\n    tplRegOp_desenharCamposEditaveis_();\n  }\n  function tplRegOp_removerCampoEdicao_(id) {\n    tplRegOp_camposEmEdicao_ = tplRegOp_camposEmEdicao_.filter(c => c.id !== id);\n    tplRegOp_desenharCamposEditaveis_();\n  }\n  function tplRegOp_adicionarCampoEdicao_() {\n    tplRegOp_camposEmEdicao_.push({ id: tplRegOp_gerarIdLocal_(), rotulo: '', tipo: 'texto', secao: '', usarIA: false });\n    tplRegOp_desenharCamposEditaveis_();\n  }\n  function tplRegOp_atualizarAssinaturaEdicao_(id, valor) {\n    const item = tplRegOp_assinaturasEmEdicao_.find(a => a.id === id);\n    if (item) item.papel = valor;\n  }\n  function tplRegOp_removerAssinaturaEdicao_(id) {\n    tplRegOp_assinaturasEmEdicao_ = tplRegOp_assinaturasEmEdicao_.filter(a => a.id !== id);\n    tplRegOp_desenharCamposEditaveis_();\n  }\n  function tplRegOp_adicionarAssinaturaEdicao_() {\n    tplRegOp_assinaturasEmEdicao_.push({ id: tplRegOp_gerarIdLocal_(), papel: '' });\n    tplRegOp_desenharCamposEditaveis_();\n  }\n  function tplRegOp_atualizarAbrePendencia_(checked) {\n    if (!tplRegOp_novoTipoContexto_) return;\n    tplRegOp_novoTipoContexto_.abrePendencia = checked;\n    const fechWrap = tplRegOp_el('tplRegOp_tipoFechamentoWrap');\n    if (fechWrap) fechWrap.style.display = checked ? '' : 'none';\n  }\n  function tplRegOp_atualizarTipoFechamento_(valor) {\n    if (!tplRegOp_novoTipoContexto_) return;\n    tplRegOp_novoTipoContexto_.tipoFechamentoId = valor;\n  }\n\n  async function tplRegOp_salvarTipoDocumento_() {\n    const campos = tplRegOp_camposEmEdicao_.filter(c => c.rotulo.trim()).map(c => ({ rotulo: c.rotulo.trim(), tipo: c.tipo, secao: c.secao.trim(), usarIA: !!c.usarIA }));\n    const assinaturas = tplRegOp_assinaturasEmEdicao_.filter(a => a.papel.trim()).map(a => a.papel.trim());\n    if (!campos.length) {\n      tplRegOp_writeLog('Informe pelo menos 1 campo antes de salvar.', 'AVISO');\n      return;\n    }\n    const ctx = tplRegOp_novoTipoContexto_;\n    if (!ctx) {\n      tplRegOp_writeLog('Monte os campos (com a IA ou manualmente) antes de salvar.', 'AVISO');\n      return;\n    }\n    const nomeEl = tplRegOp_el('tplRegOp_novoTipoNome');\n    if (nomeEl) ctx.nome = nomeEl.value.trim();\n    if (!ctx.nome) {\n      tplRegOp_writeLog('Informe o nome do tipo de documento antes de salvar.', 'AVISO');\n      return;\n    }\n    if (document.getElementById('tplRegOp_novoTipoPopsWrap')) {\n      ctx.pops = Array.from(document.querySelectorAll('#tplRegOp_novoTipoPopsWrap input:checked')).map(cb => ({ codigo: cb.value, nome: cb.dataset.nome }));\n    }\n    tplRegOp_writeLog('Salvando tipo de documento \"' + ctx.nome + '\"...');\n    try {\n      const r = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiSalvarTipoDocumento', {\n        id: ctx.id || undefined,\n        nome: ctx.nome,\n        popsRelacionados: ctx.pops,\n        campos: campos,\n        assinaturas: assinaturas,\n        abrePendencia: !!ctx.abrePendencia,\n        tipoFechamentoId: ctx.tipoFechamentoId || ''\n      }), 'salvar tipo de documento');\n      if (!r.ok) {\n        tplRegOp_writeLog('Falha ao salvar: ' + r.mensagem, 'ERRO');\n        return;\n      }\n      const novoTipo = {\n        id: r.id, nome: ctx.nome, popsRelacionados: ctx.pops, campos: campos, assinaturas: assinaturas,\n        abrePendencia: !!ctx.abrePendencia, tipoFechamentoId: ctx.tipoFechamentoId || ''\n      };\n      const idxExistente = tplRegOp_tiposDocumento_.findIndex(t => t.id === r.id);\n      if (idxExistente >= 0) tplRegOp_tiposDocumento_[idxExistente] = novoTipo;\n      else tplRegOp_tiposDocumento_.push(novoTipo);\n      tplRegOp_tipoDocumentoAtual_ = novoTipo;\n      tplRegOp_renderSelectTipoDocumento_();\n      tplRegOp_el('tplRegOp_selectTipoDoc').value = novoTipo.id;\n      tplRegOp_el('tplRegOp_novoTipoFormWrap').innerHTML = '';\n      tplRegOp_el('tplRegOp_camposEditWrap').innerHTML = '';\n      tplRegOp_renderResumoTipo_(novoTipo);\n      tplRegOp_el('tplRegOp_btnAvancarPreenchimento').disabled = false;\n      tplRegOp_writeLog('Tipo de documento salvo com sucesso (' + campos.length + ' campo(s)).', 'SUCESSO');\n    } catch (e) {\n      tplRegOp_writeLog('Erro ao salvar tipo de documento: ' + (e && e.message ? e.message : e), 'ERRO');\n    }\n  }\n\n  function tplRegOp_irParaPreenchimento_() {\n    if (!tplRegOp_tipoDocumentoAtual_) {\n      tplRegOp_writeLog('Escolha ou crie um tipo de documento antes de avançar.', 'AVISO');\n      return;\n    }\n    tplRegOp_fechandoPendenciaId_ = null;\n    tplRegOp_el('tplRegOp_resumoTipoWrap').textContent = 'Tipo de documento: ' + tplRegOp_tipoDocumentoAtual_.nome;\n    tplRegOp_renderPreenchimentoDinamico_();\n    tplRegOp_irParaEtapa(3);\n  }\n\n  // ============================================================\n  // PASSO 3 — PREENCHIMENTO (campos + assinaturas dinâmicos)\n  // ============================================================\n  function tplRegOp_renderPreenchimentoDinamico_() {\n    const tipo = tplRegOp_tipoDocumentoAtual_;\n    const campos = tipo.campos || [];\n    const wrap = tplRegOp_el('tplRegOp_camposPreenchimentoWrap');\n\n    const grupos = [];\n    const indice = {};\n    campos.forEach((c) => {\n      const secao = (c.secao || '').trim();\n      if (!(secao in indice)) { indice[secao] = grupos.length; grupos.push({ secao: secao, itens: [] }); }\n      grupos[indice[secao]].itens.push(c);\n    });\n\n    wrap.innerHTML = grupos.map((grupo) => {\n      const cabecalho = grupo.secao ? '<div class=\"section-divider\">' + tplRegOp_escapeHtml_(grupo.secao) + '</div>' : '';\n      const itensHtml = grupo.itens.map((item) => {\n        const idx = campos.indexOf(item);\n        let controle = '';\n        if (item.tipo === 'sim_nao_na') {\n          controle = `\n            <div class=\"resposta-opcoes\">\n              <label><input type=\"radio\" name=\"tplRegOp_campo_${idx}\" value=\"Sim\"> Sim</label>\n              <label><input type=\"radio\" name=\"tplRegOp_campo_${idx}\" value=\"Não\"> Não</label>\n              <label><input type=\"radio\" name=\"tplRegOp_campo_${idx}\" value=\"N/A\"> N/A</label>\n            </div>`;\n        } else if (item.tipo === 'texto' && item.usarIA) {\n          controle = `<textarea class=\"form-control\" id=\"tplRegOp_campo_${idx}\" placeholder=\"Descreva aqui...\"></textarea>` +\n            `<div class=\"btn-container\"><button type=\"button\" class=\"btn btn-secondary btn-xs\" onclick=\"tplRegOp_melhorarCampo_(${idx})\">Revisar texto (IA)</button></div>` +\n            `<div id=\"tplRegOp_iaWrap_${idx}\"></div>`;\n        } else {\n          const tipoInput = item.tipo === 'numero' ? 'number' : 'text';\n          const placeholder = item.tipo === 'data' ? 'dd/mm/aaaa' : '';\n          controle = `<input type=\"${tipoInput}\" class=\"form-control\" id=\"tplRegOp_campo_${idx}\" placeholder=\"${placeholder}\">`;\n        }\n        return `\n          <div class=\"item-checklist item-checklist-preenchimento\" data-idx=\"${idx}\">\n            <div class=\"item-texto\">${tplRegOp_escapeHtml_(item.rotulo)}</div>\n            ${controle}\n          </div>\n        `;\n      }).join('');\n      return cabecalho + itensHtml;\n    }).join('');\n\n    const assinWrap = tplRegOp_el('tplRegOp_assinaturasPreenchimentoWrap');\n    assinWrap.innerHTML = (tipo.assinaturas || []).map((papel, i) => `\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>${tplRegOp_escapeHtml_(papel)} — Nome</label>\n          <input type=\"text\" class=\"form-control\" id=\"tplRegOp_assinNome_${i}\">\n        </div>\n        <div class=\"form-group\">\n          <label>${tplRegOp_escapeHtml_(papel)} — Cargo</label>\n          <input type=\"text\" class=\"form-control\" id=\"tplRegOp_assinCargo_${i}\">\n        </div>\n      </div>\n    `).join('');\n  }\n\n  let tplRegOp_sugestoesIA_ = {}; // idx -> texto melhorado, aguardando decisão do colaborador\n\n  async function tplRegOp_melhorarCampo_(idx) {\n    const campos = (tplRegOp_tipoDocumentoAtual_ && tplRegOp_tipoDocumentoAtual_.campos) || [];\n    const item = campos[idx];\n    const el = tplRegOp_el('tplRegOp_campo_' + idx);\n    const iaWrap = tplRegOp_el('tplRegOp_iaWrap_' + idx);\n    if (!el || !item) return;\n    const valorOriginal = el.value.trim();\n    if (!valorOriginal) {\n      tplRegOp_writeLog('Escreva algo no campo \"' + item.rotulo + '\" antes de pedir a melhoria da IA.', 'AVISO');\n      return;\n    }\n    iaWrap.innerHTML = '<div class=\"alert-box info\">Melhorando texto com IA...</div>';\n    try {\n      const r = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiMelhorarTextoCampo', {\n        rotulo: item.rotulo,\n        valorOriginal: valorOriginal,\n        tipoDocumentoNome: tplRegOp_tipoDocumentoAtual_.nome\n      }), 'melhorar texto');\n      if (!r.ok) {\n        iaWrap.innerHTML = '<div class=\"alert-box error\">' + tplRegOp_escapeHtml_(r.mensagem) + '</div>';\n        return;\n      }\n      tplRegOp_sugestoesIA_[idx] = r.textoMelhorado;\n      iaWrap.innerHTML = `\n        <div class=\"ia-melhoria-wrap\">\n          <span class=\"ia-label\">Original</span>\n          <div class=\"ia-original\">${tplRegOp_escapeHtml_(valorOriginal)}</div>\n          <span class=\"ia-label\">Sugestão da IA</span>\n          <div class=\"ia-sugestao\">${tplRegOp_escapeHtml_(r.textoMelhorado)}</div>\n          <div class=\"btn-container\">\n            <button type=\"button\" class=\"btn btn-primary btn-xs\" onclick=\"tplRegOp_usarSugestaoIA_(${idx})\">Usar sugestão da IA</button>\n            <button type=\"button\" class=\"btn btn-secondary btn-xs\" onclick=\"tplRegOp_descartarSugestaoIA_(${idx})\">Manter o que escrevi</button>\n          </div>\n        </div>\n      `;\n    } catch (e) {\n      iaWrap.innerHTML = '<div class=\"alert-box error\">Erro: ' + tplRegOp_escapeHtml_(e && e.message ? e.message : e) + '</div>';\n    }\n  }\n  function tplRegOp_usarSugestaoIA_(idx) {\n    const el = tplRegOp_el('tplRegOp_campo_' + idx);\n    if (el && tplRegOp_sugestoesIA_[idx] !== undefined) el.value = tplRegOp_sugestoesIA_[idx];\n    tplRegOp_descartarSugestaoIA_(idx);\n  }\n  function tplRegOp_descartarSugestaoIA_(idx) {\n    delete tplRegOp_sugestoesIA_[idx];\n    const iaWrap = tplRegOp_el('tplRegOp_iaWrap_' + idx);\n    if (iaWrap) iaWrap.innerHTML = '';\n  }\n\n  function tplRegOp_coletarRespostas_() {\n    const campos = (tplRegOp_tipoDocumentoAtual_ && tplRegOp_tipoDocumentoAtual_.campos) || [];\n    return campos.map((item, i) => {\n      let valor = '';\n      if (item.tipo === 'sim_nao_na') {\n        const marcado = document.querySelector('input[name=\"tplRegOp_campo_' + i + '\"]:checked');\n        valor = marcado ? marcado.value : '';\n      } else {\n        const el = tplRegOp_el('tplRegOp_campo_' + i);\n        valor = el ? el.value : '';\n      }\n      return { rotulo: item.rotulo, tipo: item.tipo, secao: item.secao || '', valor: valor };\n    });\n  }\n\n  function tplRegOp_coletarAssinaturas_() {\n    const papeis = (tplRegOp_tipoDocumentoAtual_ && tplRegOp_tipoDocumentoAtual_.assinaturas) || [];\n    return papeis.map((papel, i) => ({\n      papel: papel,\n      nome: (tplRegOp_el('tplRegOp_assinNome_' + i) || {}).value || '',\n      cargo: (tplRegOp_el('tplRegOp_assinCargo_' + i) || {}).value || ''\n    }));\n  }\n\n  function tplRegOp_renderImgSlots_() {\n    const wrap = tplRegOp_el('tplRegOp_imagensWrap');\n    if (!tplRegOp_imagens_.length) { wrap.innerHTML = '<div style=\"color: var(--muted); font-size: 11px; margin-top: 6px;\">Nenhuma foto anexada.</div>'; return; }\n    wrap.innerHTML = '<div class=\"img-slot-list\">' + tplRegOp_imagens_.map((img, i) => `\n      <div class=\"img-slot\">\n        <img src=\"data:${img.mimeType};base64,${img.base64}\" alt=\"Foto ${i + 1}\">\n        <input type=\"text\" placeholder=\"Legenda\" value=\"${tplRegOp_escapeHtml_(img.legenda)}\" onchange=\"tplRegOp_atualizarLegendaImagem_(${i}, this.value)\">\n        <button type=\"button\" class=\"btn btn-danger btn-xs\" onclick=\"tplRegOp_removerImagem_(${i})\">Remover</button>\n      </div>\n    `).join('') + '</div>';\n  }\n  async function tplRegOp_addImagens_(input) {\n    const arquivos = Array.from(input.files || []);\n    const novas = await Promise.all(arquivos.map(arquivo => new Promise((resolve, reject) => {\n      const reader = new FileReader();\n      reader.onload = () => {\n        const resultado = String(reader.result || '');\n        const base64 = resultado.split(',')[1] || '';\n        resolve({ base64: base64, mimeType: arquivo.type || 'image/jpeg', legenda: '' });\n      };\n      reader.onerror = reject;\n      reader.readAsDataURL(arquivo);\n    })));\n    tplRegOp_imagens_ = tplRegOp_imagens_.concat(novas);\n    input.value = '';\n    tplRegOp_renderImgSlots_();\n  }\n  function tplRegOp_atualizarLegendaImagem_(i, valor) { tplRegOp_imagens_[i].legenda = valor; }\n  function tplRegOp_removerImagem_(i) { tplRegOp_imagens_.splice(i, 1); tplRegOp_renderImgSlots_(); }\n\n  async function tplRegOp_gerarRegistro() {\n    const hospital = tplRegOp_obterHospital_();\n    if (!hospital.razaoSocial) {\n      tplRegOp_writeLog('Informe os dados do hospital na etapa 1 antes de gerar.', 'ERRO');\n      tplRegOp_irParaEtapa(1);\n      return;\n    }\n    if (!tplRegOp_tipoDocumentoAtual_) {\n      tplRegOp_writeLog('Escolha o tipo de documento na etapa 2 antes de gerar.', 'ERRO');\n      tplRegOp_irParaEtapa(2);\n      return;\n    }\n    const assinaturas = tplRegOp_coletarAssinaturas_();\n    const semNome = assinaturas.find(a => !a.nome.trim());\n    if (semNome) {\n      tplRegOp_writeLog('Preencha o nome do responsável \"' + semNome.papel + '\" antes de gerar.', 'ERRO');\n      return;\n    }\n\n    // Abre a aba em branco JÁ, direto no clique (síncrono) — evita\n    // bloqueio de pop-up do navegador (mesma lição de 2026-08-14 no\n    // módulo PGT e POP).\n    const win = window.open('', '_blank');\n    if (win) {\n      win.document.write('<p style=\"font-family:sans-serif;color:#555;padding:24px;\">Gerando registro, aguarde...</p>');\n    } else {\n      tplRegOp_writeLog('O navegador bloqueou a abertura da nova aba (pop-up). Permita pop-ups pra este site e tente de novo.', 'AVISO');\n    }\n\n    const btn = tplRegOp_el('tplRegOp_btnGerar');\n    btn.disabled = true;\n    tplRegOp_writeLog('Gerando registro: ' + tplRegOp_tipoDocumentoAtual_.nome + '...');\n    try {\n      const payload = {\n        hospital: hospital,\n        tipoDocumentoId: tplRegOp_tipoDocumentoAtual_.id,\n        tipoDocumentoNome: tplRegOp_tipoDocumentoAtual_.nome,\n        data: tplRegOp_el('tplRegOp_data').value,\n        respostas: tplRegOp_coletarRespostas_(),\n        assinaturas: assinaturas,\n        observacoesGerais: tplRegOp_el('tplRegOp_observacoesGerais').value,\n        imagens: tplRegOp_imagens_,\n        fechaRegistroId: tplRegOp_fechandoPendenciaId_ || undefined\n      };\n      const r = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiGerarRegistro', payload), 'gerar registro');\n      if (!r.ok) {\n        tplRegOp_writeLog('Falha ao gerar registro: ' + r.mensagem, 'ERRO');\n        tplRegOp_el('tplRegOp_resultadoWrap').innerHTML = '<div class=\"alert-box error\">' + tplRegOp_escapeHtml_(r.mensagem) + '</div>';\n        if (win) win.document.write('<p style=\"font-family:sans-serif;color:#b91c1c;padding:24px;\">Erro: ' + tplRegOp_escapeHtml_(r.mensagem) + '</p>');\n        return;\n      }\n      if (win) {\n        win.document.open();\n        win.document.write(r.html);\n        win.document.close();\n      }\n      tplRegOp_el('tplRegOp_resultadoWrap').innerHTML = '<div class=\"alert-box success\">Registro gerado.' +\n        (r.pdfUrl ? (' <a href=\"' + r.pdfUrl + '\" target=\"_blank\" rel=\"noopener\">Abrir PDF salvo</a>') : '') + '</div>';\n      tplRegOp_writeLog('Registro gerado' + (r.pdfUrl ? ' e PDF salvo.' : '.'), 'SUCESSO');\n      [r.avisoPdf, r.avisoHtml].filter(Boolean).forEach(function (aviso) {\n        tplRegOp_writeLog(aviso, 'AVISO');\n        tplRegOp_el('tplRegOp_resultadoWrap').innerHTML += '<div class=\"alert-box warning\">' + tplRegOp_escapeHtml_(aviso) + '</div>';\n      });\n      tplRegOp_fechandoPendenciaId_ = null;\n      tplRegOp_sugestoesIA_ = {};\n    } catch (e) {\n      const msg = (e && e.message ? e.message : e);\n      tplRegOp_writeLog('Erro ao gerar registro: ' + msg, 'ERRO');\n      tplRegOp_el('tplRegOp_resultadoWrap').innerHTML = '<div class=\"alert-box error\">Erro: ' + tplRegOp_escapeHtml_(msg) + '</div>';\n      if (win) win.document.write('<p style=\"font-family:sans-serif;color:#b91c1c;padding:24px;\">Erro: ' + tplRegOp_escapeHtml_(msg) + '</p>');\n    } finally {\n      btn.disabled = false;\n    }\n  }\n\n  // ============================================================\n  // PASSO 4 — CONSULTAR\n  // ============================================================\n  let tplRegOp_cnpjConsultadoAtual_ = '';\n\n  async function tplRegOp_consultarRegistros_() {\n    const cnpj = tplRegOp_el('tplRegOp_cnpjConsulta').value;\n    const wrap = tplRegOp_el('tplRegOp_consultaWrap');\n    const pendWrap = tplRegOp_el('tplRegOp_pendenciasWrap');\n    if (!cnpj || !cnpj.trim()) {\n      wrap.innerHTML = '<div class=\"alert-box warning\">Informe o CNPJ antes de consultar.</div>';\n      return;\n    }\n    tplRegOp_cnpjConsultadoAtual_ = cnpj;\n    wrap.innerHTML = '<div class=\"alert-box info\">Consultando...</div>';\n    pendWrap.innerHTML = '<div class=\"alert-box info\">Consultando...</div>';\n    tplRegOp_writeLog('Consultando registros já gerados para o CNPJ ' + cnpj + '...');\n\n    try {\n      const rPend = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiListarRegistrosPendentes', { cnpj: cnpj }), 'consultar pendências');\n      if (!rPend.ok) {\n        pendWrap.innerHTML = '<div class=\"alert-box error\">' + tplRegOp_escapeHtml_(rPend.mensagem) + '</div>';\n      } else if (!rPend.pendentes.length) {\n        pendWrap.innerHTML = '<div class=\"alert-box success\">Nenhuma pendência em aberto pra este CNPJ.</div>';\n      } else {\n        pendWrap.innerHTML = rPend.pendentes.map(p => `\n          <div class=\"pendencia-item\">\n            <div class=\"pendencia-titulo\">${tplRegOp_escapeHtml_(p.tipoDocumentoNome)} <span style=\"color:var(--muted);font-weight:400;\">(aberto em ${tplRegOp_escapeHtml_(p.data)})</span></div>\n            <button type=\"button\" class=\"btn btn-primary btn-xs\" onclick=\"tplRegOp_registrarFechamento_('${p.id}', '${p.tipoDocumentoId}')\">Registrar Fechamento</button>\n          </div>\n        `).join('');\n      }\n    } catch (e) {\n      pendWrap.innerHTML = '<div class=\"alert-box error\">Erro ao consultar pendências: ' + tplRegOp_escapeHtml_(e && e.message ? e.message : e) + '</div>';\n    }\n\n    try {\n      const r = tplRegOp_verificarResposta_(await tplRegOp_dispatch_('apiListarArquivosPdf', { cnpj: cnpj }), 'consultar registros');\n      if (!r.ok) {\n        wrap.innerHTML = '<div class=\"alert-box error\">' + tplRegOp_escapeHtml_(r.mensagem) + '</div>';\n        tplRegOp_writeLog('Consulta falhou: ' + r.mensagem, 'ERRO');\n        return;\n      }\n      if (!r.arquivos.length) {\n        wrap.innerHTML = '<div class=\"alert-box info\">Nenhum registro encontrado pra este CNPJ ainda.</div>';\n        tplRegOp_writeLog('Nenhum registro encontrado pra este CNPJ.');\n        return;\n      }\n      wrap.innerHTML = '<div class=\"alert-box success\">' + r.arquivos.length + ' registro(s) encontrado(s):</div>' +\n        r.arquivos.map(a => `\n          <div class=\"doc-item\">\n            <div class=\"doc-titulo\">${tplRegOp_escapeHtml_(a.nome)} <span style=\"color:var(--muted);font-weight:400;\">(${tplRegOp_escapeHtml_(a.data)})</span></div>\n            <a class=\"btn btn-secondary\" href=\"${a.url}\" target=\"_blank\" rel=\"noopener\">Abrir PDF</a>\n          </div>\n        `).join('');\n      tplRegOp_writeLog(r.arquivos.length + ' registro(s) encontrado(s).', 'SUCESSO');\n    } catch (e) {\n      const msg = (e && e.message ? e.message : e);\n      wrap.innerHTML = '<div class=\"alert-box error\">Erro ao consultar: ' + tplRegOp_escapeHtml_(msg) + '</div>';\n      tplRegOp_writeLog('Erro ao consultar registros: ' + msg, 'ERRO');\n    }\n  }\n\n  /** Leva à etapa 4 já com o CNPJ da etapa 1 (e consulta, se houver CNPJ). */\n  function tplRegOp_abrirConsulta_() {\n    const campo = tplRegOp_el('tplRegOp_cnpjConsulta');\n    const cnpjEtapa1 = (tplRegOp_el('tplRegOp_cnpj').value || '').trim();\n    if (campo && !campo.value.trim() && cnpjEtapa1) campo.value = cnpjEtapa1;\n    tplRegOp_irParaEtapa(4);\n    if (campo && campo.value.trim()) tplRegOp_consultarRegistros_();\n  }\n\n  function tplRegOp_registrarFechamento_(registroOrigemId, tipoDocumentoIdOrigem) {\n    const tipoOrigem = tplRegOp_tiposDocumento_.find(t => t.id === tipoDocumentoIdOrigem);\n    if (!tipoOrigem) {\n      tplRegOp_writeLog('Não encontrei o tipo de documento de origem desta pendência.', 'ERRO');\n      return;\n    }\n    if (!tipoOrigem.tipoFechamentoId) {\n      tplRegOp_writeLog('O tipo \"' + tipoOrigem.nome + '\" não tem documento de fechamento configurado — edite esse tipo na etapa 2 e defina qual documento fecha esta pendência.', 'AVISO');\n      return;\n    }\n    const tipoFechamento = tplRegOp_tiposDocumento_.find(t => t.id === tipoOrigem.tipoFechamentoId);\n    if (!tipoFechamento) {\n      tplRegOp_writeLog('O documento de fechamento configurado pra \"' + tipoOrigem.nome + '\" não foi encontrado (pode ter sido excluído) — edite o tipo e escolha outro.', 'ERRO');\n      return;\n    }\n    if (tplRegOp_cnpjConsultadoAtual_) {\n      const digitos = (v) => String(v || '').replace(/[^0-9]/g, '');\n      const cnpjEtapa1 = tplRegOp_el('tplRegOp_cnpj').value;\n      if (digitos(cnpjEtapa1) !== digitos(tplRegOp_cnpjConsultadoAtual_)) {\n        // A pendência é deste CNPJ: troca o hospital da etapa 1 e busca os dados.\n        tplRegOp_el('tplRegOp_cnpj').value = tplRegOp_cnpjConsultadoAtual_;\n        tplRegOp_el('tplRegOp_hospital').value = '';\n        tplRegOp_el('tplRegOp_cidade').value = '';\n        tplRegOp_el('tplRegOp_uf').value = '';\n        tplRegOp_buscarCNPJ();\n      }\n    }\n    tplRegOp_tipoDocumentoAtual_ = tipoFechamento;\n    tplRegOp_fechandoPendenciaId_ = registroOrigemId;\n    tplRegOp_el('tplRegOp_resumoTipoWrap').textContent = 'Tipo de documento: ' + tipoFechamento.nome + ' (fechando pendência)';\n    tplRegOp_renderPreenchimentoDinamico_();\n    tplRegOp_writeLog('Fechando pendência com o documento \"' + tipoFechamento.nome + '\" — confira os dados do hospital antes de gerar.', 'AVISO');\n    tplRegOp_irParaEtapa(3);\n  }\n\n  // ============================================================\n  // RENDER REAL (chamado pelo loader após o eval)\n  // ============================================================\n  function tplRegOp_renderReal_() {\n    const container = document.getElementById('tplRegOpContainer');\n    if (!container) return;\n    container.innerHTML = TPL_REGOP_HTML_;\n    tplRegOp_inicializar();\n  }\n</script>\n";

function RegOp_obterConteudoModulo() {
  return REGOP_CONTEUDO_MODULO;
}
